css:
.accbydesign-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #34302a;
    background: linear-gradient(180deg, #faf6ee 0%, #f3ece0 100%);
    border-radius: 18px;
}

.accbydesign-container * {
    box-sizing: border-box;
}

.accbydesign-header {
    text-align: center;
    padding: 28px 22px 24px;
    background: linear-gradient(135deg, #1f3d2f 0%, #2e5a44 55%, #5a2030 100%);
    color: #f6efe2;
    border-radius: 16px;
    margin-bottom: 20px;
    border: 1px solid #1a3327;
    box-shadow: 0 12px 34px rgba(31, 61, 47, 0.28);
}

.accbydesign-header h1 {
    margin: 8px 0 10px;
    font-family: Georgia, 'Times New Roman', serif;
    font-size: 2.4rem;
    font-weight: 700;
    letter-spacing: -0.4px;
    color: #fbf6ec;
}

.accbydesign-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.2px;
    font-weight: 700;
    color: #e9c87a;
    background: rgba(233, 200, 122, 0.14);
    border: 1px solid rgba(233, 200, 122, 0.36);
    padding: 5px 14px;
    border-radius: 999px;
}

.accbydesign-subtitle {
    margin: 0 auto;
    max-width: 820px;
    font-size: 1rem;
    line-height: 1.6;
    color: #e8ddca;
}

.accbydesign-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #6b6356;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.accbydesign-period-counter #currentDay,
.accbydesign-period-counter #maxPeriods {
    font-weight: 800;
    color: #2e5a44;
}

.accbydesign-round-name {
    background: rgba(46, 90, 68, 0.12);
    color: #2e5a44;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.accbydesign-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #8a2a3c;
    background: rgba(138, 42, 60, 0.10);
    border: 1px solid rgba(138, 42, 60, 0.28);
    padding: 4px 12px;
    border-radius: 999px;
}

.accbydesign-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.accbydesign-status-card {
    background: #ffffff;
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid #e7ddca;
    box-shadow: 0 6px 16px rgba(52, 48, 42, 0.08);
    border-top: 4px solid #2e5a44;
}

.accbydesign-card-validity { border-top-color: #2e5a44; }
.accbydesign-card-clarity { border-top-color: #3f6fa3; }
.accbydesign-card-completion { border-top-color: #c08a2e; }
.accbydesign-card-risk { border-top-color: #8a2a3c; }

.accbydesign-label {
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #8a8170;
}

.accbydesign-value {
    font-size: 2.6rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #2a2722;
    font-variant-numeric: tabular-nums;
}

.accbydesign-card-validity .accbydesign-value { color: #2e5a44; }
.accbydesign-card-clarity .accbydesign-value { color: #3f6fa3; }
.accbydesign-card-completion .accbydesign-value { color: #b07d22; }
.accbydesign-card-risk .accbydesign-value { color: #8a2a3c; }

.accbydesign-sublabel {
    font-size: 0.76rem;
    color: #8a8170;
    line-height: 1.35;
}

.accbydesign-completion-low { border-top-color: #c0392b; }
.accbydesign-completion-low .accbydesign-value { color: #c0392b; }
.accbydesign-completion-high { border-top-color: #2e7d32; }
.accbydesign-completion-high .accbydesign-value { color: #2e7d32; }

.accbydesign-risk-high { border-top-color: #c0392b; }
.accbydesign-risk-high .accbydesign-value { color: #c0392b; }
.accbydesign-risk-low { border-top-color: #2e7d32; }
.accbydesign-risk-low .accbydesign-value { color: #2e7d32; }

.accbydesign-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #fffaf0;
    border: 1px solid #e7ddca;
    color: #4a443b;
    padding: 11px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
}

.accbydesign-budget-bar #budgetDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
    color: #2e5a44;
}

.accbydesign-briefing {
    display: flex;
    gap: 14px;
    background: #ffffff;
    border-left: 5px solid #2e5a44;
    border-radius: 12px;
    padding: 18px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(52, 48, 42, 0.08);
}

.accbydesign-briefing-icon {
    font-size: 1.9rem;
    line-height: 1;
}

.accbydesign-briefing-title {
    font-family: Georgia, 'Times New Roman', serif;
    font-weight: 700;
    font-size: 1.15rem;
    color: #1f3d2f;
    margin-bottom: 6px;
}

.accbydesign-briefing-text {
    font-size: 0.96rem;
    line-height: 1.6;
    color: #4a443b;
}

.accbydesign-briefing-text strong { color: #2e5a44; }
.accbydesign-briefing-text em { color: #8a2a3c; font-style: italic; }

.accbydesign-controls {
    background: #ffffff;
    border-radius: 14px;
    padding: 22px 24px;
    margin-bottom: 18px;
    border: 1px solid #e7ddca;
    box-shadow: 0 6px 16px rgba(52, 48, 42, 0.08);
}

.accbydesign-controls h3 {
    margin: 0 0 16px;
    font-family: Georgia, 'Times New Roman', serif;
    font-size: 1.18rem;
    font-weight: 700;
    color: #1f3d2f;
    border-bottom: 2px solid #efe6d4;
    padding-bottom: 8px;
}

.accbydesign-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #3a352d;
    margin: 16px 0 6px;
}

.accbydesign-container select,
.accbydesign-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #d4c8af;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #fffdf8;
    color: #2a2722;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.accbydesign-container select:focus,
.accbydesign-container input[type="number"]:focus {
    outline: none;
    border-color: #2e5a44;
    box-shadow: 0 0 0 3px rgba(46, 90, 68, 0.16);
}

.accbydesign-container select option {
    background-color: #fffdf8;
    color: #2a2722;
}

.accbydesign-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #2e5a44;
}

.accbydesign-range-readout,
.accbydesign-alloc-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #6b6356;
    margin-top: 4px;
}

.accbydesign-range-readout span:last-child,
.accbydesign-alloc-readout span:nth-child(2) {
    color: #2e5a44;
    font-weight: 800;
}

.accbydesign-hint {
    font-size: 0.8rem;
    color: #8a8170;
    margin-top: 6px;
    line-height: 1.45;
    background: #faf6ee;
    border-radius: 8px;
    padding: 8px 10px;
}

.accbydesign-alloc-grid {
    display: flex;
    flex-direction: column;
    gap: 8px;
    margin-top: 4px;
}

.accbydesign-alloc-row {
    display: flex;
    align-items: center;
    gap: 12px;
    background: #faf6ee;
    border: 1px solid #e7ddca;
    border-radius: 9px;
    padding: 9px 12px;
}

.accbydesign-alloc-name {
    flex: 1;
    font-size: 0.88rem;
    font-weight: 600;
    color: #4a443b;
}

.accbydesign-alloc-row input[type="number"] {
    width: 92px;
    flex: 0 0 92px;
}

.accbydesign-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.accbydesign-container .btn-primary {
    background: linear-gradient(135deg, #1f3d2f 0%, #2e5a44 100%);
    border: none;
    color: #f6efe2;
    padding: 11px 28px;
    border-radius: 9px;
    box-shadow: 0 8px 20px rgba(31, 61, 47, 0.30);
}

.accbydesign-container .btn-primary:hover {
    filter: brightness(1.10);
}

.accbydesign-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: #d4c8af;
    color: #6b6356;
    background: transparent;
}

.accbydesign-coach {
    background: linear-gradient(135deg, #5a2030 0%, #3d1622 100%);
    color: #f3e6d8;
    border: 1px solid #4a1a26;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(90, 32, 48, 0.22);
}

.accbydesign-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #e9c87a;
    margin-bottom: 8px;
}

.accbydesign-coach-body {
    font-size: 0.95rem;
    line-height: 1.6;
}

.accbydesign-coach-body strong { color: #f0d79a; }
.accbydesign-coach-body em { color: #f3b6c0; font-style: italic; }

.accbydesign-history,
.accbydesign-chart {
    background: #ffffff;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #e7ddca;
    box-shadow: 0 6px 16px rgba(52, 48, 42, 0.08);
}

.accbydesign-history h3,
.accbydesign-chart h3 {
    margin: 0 0 14px;
    font-family: Georgia, 'Times New Roman', serif;
    font-size: 1.12rem;
    font-weight: 700;
    color: #1f3d2f;
}

.accbydesign-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #4a443b;
}

.accbydesign-container table#usfHistoryTable th {
    background: #f3ece0;
    color: #1f3d2f;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #e0d4bd;
}

.accbydesign-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #efe6d4;
    color: #4a443b;
}

.accbydesign-container table#usfHistoryTable tr:nth-child(even) td {
    background: #fbf7ef;
}

.accbydesign-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .accbydesign-container {
        padding: 14px;
    }
    .accbydesign-header h1 {
        font-size: 1.8rem;
    }
    .accbydesign-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .accbydesign-value {
        font-size: 2.1rem;
    }
    .accbydesign-clock {
        margin-left: 0;
    }
    .accbydesign-period-counter {
        font-size: 0.88rem;
    }
    .accbydesign-budget-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .accbydesign-alloc-row {
        flex-wrap: wrap;
    }
    .accbydesign-alloc-row input[type="number"] {
        width: 100%;
        flex: 1 1 100%;
    }
    .accbydesign-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}


/* ---- v1.1.0 completion / debrief screen (accbydesign) ---- */
.accbydesign-completion { padding: 8px 4px 4px; }
.accbydesign-cm-head { text-align: center; margin-bottom: 16px; }
.accbydesign-cm-score { font-size: 3.2rem; font-weight: 800; line-height: 1; color: #4a6a8a; }
.accbydesign-cm-score-max { font-size: 1.2rem; font-weight: 600; color: #83a0b8; }
.accbydesign-cm-grade { font-size: 1.15rem; font-weight: 700; margin-top: 6px; color: #22303a; }
.accbydesign-cm-badge { display: inline-block; margin-left: 6px; padding: 2px 10px; border-radius: 999px; font-size: 0.78rem; font-weight: 700; vertical-align: middle; }
.accbydesign-cm-yes { background: rgba(74,106,138,0.16); color: #4a6a8a; border: 1px solid rgba(74,106,138,0.5); }
.accbydesign-cm-no { background: rgba(180,70,55,0.12); color: #a5412c; border: 1px solid rgba(180,70,55,0.45); }
.accbydesign-cm-metrics { display: flex; flex-wrap: wrap; gap: 10px; justify-content: center; margin: 12px 0 16px; }
.accbydesign-cm-metric { flex: 1 1 100px; min-width: 90px; background: rgba(74,106,138,0.08); border: 1px solid rgba(74,106,138,0.2); border-radius: 10px; padding: 10px 8px; text-align: center; }
.accbydesign-cm-mv { display: block; font-size: 1.4rem; font-weight: 800; color: #4a6a8a; }
.accbydesign-cm-ml { display: block; font-size: 0.7rem; margin-top: 4px; color: #656b7c; text-transform: uppercase; letter-spacing: 0.03em; }
.accbydesign-cm-insights-title { font-weight: 700; margin: 8px 0 6px; color: #22303a; }
.accbydesign-cm-insights { margin: 0; padding-left: 20px; }
.accbydesign-cm-insights li { margin-bottom: 8px; line-height: 1.5; font-size: 0.92rem; color: #363c4b; }

