(function() {
    'use strict';

    class AccByDesignAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Accountable by Design`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card (Highveld School of Business).
            this.COHORT = 280;               // ~280 students per cohort
            this.GROUP_WEIGHT_NOW = 70;      // current group-based grade weight (%)
            this.PASS_NOW = 88;              // current pass rate (%)
            this.COMPLETION_NOW = 92;        // current completion rate (%)
            this.FREE_RIDING = 41;           // free-riding survey signal (%)
            this.PEER_VARIANCE = 8;          // peer-eval variance explained (%)
            this.SUPPORT_BUDGET = 1.6;       // ZAR 1.6M incremental support budget
            this.HOUR_BUDGET = 600;          // ~600 marking/support hours/cohort
            this.IDEAL_OVER = 1400;          // over-budget "ideal" design cost (hrs)
            this.PILOT_DROP = 74;            // exam-heavy pilot completion drop floor (%)

            // Concept truths.
            this.TRUE_DIAGNOSIS = `alignment`;
            this.TRUE_OUTCOME = `individual`;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    validity: 25,            // does assessment evidence individual learning (0-100)
                    clarity: 20,             // visibility of individual accountability in-term (0-100)
                    completion: 92,          // projected cohort completion (%), baseline 92
                    risk: 60,                // re-moderation / accreditation risk (lower better)
                    hoursUsed: 0,            // marking + support hours committed (cap 600)
                    overBudget: false,       // blew the 600-hour budget
                    killedGroup: false,      // cut group work so far it destroys collaboration
                    cutModeration: false,    // skipped cross-section re-moderation (reliability gap)
                    completionCollapsed: false, // exam-heavy rigour without support
                    validityHistory: [25],
                    clarityHistory: [20],
                    completionHistory: [92],
                    riskHistory: [60],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Seeded defaults are a deliberately MIDDLING / wrong-leaning mix —
                // a blind click-through must not auto-win (group still at 50%, weak diagnosis).
                state.decisions = {
                    diagnosis: `passrate`,
                    outcome: `teamwork`,
                    evidence: 50,
                    exam: 20,
                    applied: 20,
                    peer: 10,
                    group: 50,
                    workload: `ignore`,
                    checkpoint: `summative`,
                    contribution: `peeronly`,
                    escalation: `advisor`,
                    targeted: 0.4,
                    writing: 0.6,
                    alert: 0.6,
                    defence: `passrate`,
                    conviction: 50
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const dg = document.getElementById(`diagnosisInput`);
                const ou = document.getElementById(`outcomeInput`);
                const ev = document.getElementById(`evidenceInput`);
                if (dg) decisions.diagnosis = dg.value;
                if (ou) decisions.outcome = ou.value;
                if (ev) decisions.evidence = parseInt(ev.value, 10);
                if (!Number.isFinite(decisions.evidence) || decisions.evidence < 0 || decisions.evidence > 100) {
                    warn(`warn_evidence_range`); return false;
                }
            } else if (round === 2) {
                const ex = document.getElementById(`examInput`);
                const ap = document.getElementById(`appliedInput`);
                const pe = document.getElementById(`peerInput`);
                const gr = document.getElementById(`groupInput`);
                const wk = document.getElementById(`workloadInput`);
                if (ex) decisions.exam = parseFloat(ex.value);
                if (ap) decisions.applied = parseFloat(ap.value);
                if (pe) decisions.peer = parseFloat(pe.value);
                if (gr) decisions.group = parseFloat(gr.value);
                if (wk) decisions.workload = wk.value;
                const parts = [decisions.exam, decisions.applied, decisions.peer, decisions.group];
                if (parts.some((v) => !Number.isFinite(v) || v < 0)) {
                    warn(`warn_weight_negative`); return false;
                }
                const total = Math.round(decisions.exam + decisions.applied + decisions.peer + decisions.group);
                if (total !== 100) {
                    warn(`warn_weight_total`); return false;
                }
            } else if (round === 3) {
                const ck = document.getElementById(`checkpointInput`);
                const co = document.getElementById(`contributionInput`);
                const es = document.getElementById(`escalationInput`);
                if (ck) decisions.checkpoint = ck.value;
                if (co) decisions.contribution = co.value;
                if (es) decisions.escalation = es.value;
            } else if (round === 4) {
                const tg = document.getElementById(`targetedInput`);
                const wr = document.getElementById(`writingInput`);
                const al = document.getElementById(`alertInput`);
                const df = document.getElementById(`defenceInput`);
                const cv = document.getElementById(`convictionInput`);
                if (tg) decisions.targeted = parseFloat(tg.value);
                if (wr) decisions.writing = parseFloat(wr.value);
                if (al) decisions.alert = parseFloat(al.value);
                if (df) decisions.defence = df.value;
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                const sparts = [decisions.targeted, decisions.writing, decisions.alert];
                if (sparts_invalid(sparts)) { warn(`warn_support_negative`); return false; }
                const stotal = Math.round((decisions.targeted + decisions.writing + decisions.alert) * 10) / 10;
                if (Math.abs(stotal - this.SUPPORT_BUDGET) > 0.001) {
                    warn(`warn_support_total`); return false;
                }
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            return true;

            function sparts_invalid(arr) {
                return arr.some((v) => !Number.isFinite(v) || v < 0);
            }
        }

        // Estimate marking/support hours for a blueprint on a 280-student cohort.
        // Exam/viva is the most costly per point; applied is efficient; peer cheap; group moderate.
        _markingHours(d) {
            const hrs = d.exam * 11 + d.applied * 5 + d.peer * 1.5 + d.group * 4;
            return Math.round(hrs);
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let validityDelta = 0, clarityDelta = 0, completionDelta = 0, riskDelta = 0, hours = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Diagnose where individual accountability disappears (constructive-alignment failure).
                switch (d.diagnosis) {
                    case `alignment`: validityDelta += 8; clarityDelta += 6; riskDelta -= 8; coachKey = `coach_r1_alignment`; break;
                    case `peeronly`: validityDelta += 1; riskDelta += 5; coachKey = `coach_r1_peeronly`; break;
                    case `passrate`: validityDelta -= 4; riskDelta += 10; coachKey = `coach_r1_passrate`; break;
                    case `teaching`: validityDelta -= 2; riskDelta += 7; coachKey = `coach_r1_teaching`; break;
                }

                // Name the most-damaged learning outcome.
                switch (d.outcome) {
                    case `individual`: validityDelta += 6; clarityDelta += 4; riskDelta -= 6; if (d.diagnosis === `alignment`) coachKey = `coach_r1_sharp`; break;
                    case `teamwork`: riskDelta += 4; coachKey = `coach_r1_teamwork`; break;
                    case `none`: validityDelta -= 4; riskDelta += 8; coachKey = `coach_r1_none`; break;
                }

                if (d.evidence >= 60) { validityDelta += 6; riskDelta -= 5; }
                else if (d.evidence <= 25) { validityDelta -= 4; riskDelta += 6; coachKey = `coach_r1_softgap`; }

                summaryKey = (d.diagnosis === `alignment` && d.outcome === `individual`) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Redesign the assessment blueprint — the validity-dominant lever (Common Errors 1, 2, 3).
                const ind = d.exam + d.applied;             // total individual-assessment weight
                const grp = d.group;
                hours = this._markingHours(d);

                // Validity rises with individual weight; the applied component is the efficient driver.
                validityDelta += (ind - 40) * 0.55 + d.applied * 0.18;
                // Clarity improves as individual ownership of the grade grows.
                clarityDelta += (ind - 40) * 0.30;

                // Peer-only-on-heavy-group is Common Error 2: it cannot substitute for direct assessment.
                if (grp >= 60 && d.peer >= 15 && ind <= 30) {
                    validityDelta -= 6; riskDelta += 8; coachKey = `coach_r2_peerbolt`;
                }

                // Exam-heavy single-instrument validity grab (Common Error 1) — flagged; completion handled later.
                if (d.exam >= 55) {
                    validityDelta += 4; riskDelta += 4; ds.completionCollapsed = true; coachKey = `coach_r2_examheavy`;
                }

                // Cutting the group project too far destroys the collaboration outcome (Decision-tree branch 5).
                if (grp < 20) {
                    validityDelta -= 6; clarityDelta -= 4; riskDelta += 16; ds.killedGroup = true; coachKey = `coach_r2_killedgroup`;
                } else if (grp >= 60) {
                    // Heavy group weighting leaves the validity gap unsolved.
                    validityDelta -= 4; riskDelta += 6; if (coachKey === `coach_default`) coachKey = `coach_r2_groupheavy`;
                }

                // A balanced, individual-evidencing blueprint that still keeps real collaboration.
                if (ind >= 45 && grp >= 25 && grp <= 50 && d.applied >= 20) {
                    validityDelta += 5; clarityDelta += 4; riskDelta -= 6;
                    if (coachKey === `coach_default`) coachKey = `coach_r2_balanced`;
                }

                // Workload posture against the ~600-hour constraint (Common Error 3).
                switch (d.workload) {
                    case `optimize`: validityDelta += 3; riskDelta -= 5; clarityDelta += 2; break;
                    case `ignore`: hours = Math.max(hours, this.IDEAL_OVER); riskDelta += 12; coachKey = `coach_r2_overbudget`; break;
                    case `cutmod`: riskDelta += 14; validityDelta -= 4; ds.cutModeration = true; coachKey = `coach_r2_cutmod`; break;
                }

                // ANY blueprint that exceeds the ~600-hour budget is unsustainable, whatever the
                // stated workload intent (a heavy exam/group mix can blow it even on "optimise").
                if (hours > this.HOUR_BUDGET) {
                    ds.overBudget = true;
                    riskDelta += 8;
                    if (coachKey === `coach_default` || coachKey === `coach_r2_balanced`) coachKey = `coach_r2_overbudget`;
                }

                summaryKey = (ind >= 45 && grp >= 25 && grp <= 50 && d.workload !== `ignore`) ? `sum_r2_good` :
                             (d.exam >= 55 ? `sum_r2_examheavy` :
                             (grp >= 60 ? `sum_r2_groupheavy` : `sum_r2_weak`));
            } else if (round === 3) {
                // Set accountability checkpoints (Common Error 4: all-summative).
                switch (d.checkpoint) {
                    case `early`: clarityDelta += 14; completionDelta += 5; riskDelta -= 8; coachKey = `coach_r3_early`; break;
                    case `mid`: clarityDelta += 5; completionDelta += 1; coachKey = `coach_r3_mid`; break;
                    case `summative`: clarityDelta -= 6; completionDelta -= 6; riskDelta += 8; coachKey = `coach_r3_summative`; break;
                }

                // Track individual contribution within the group (free-riding countermeasure).
                switch (d.contribution) {
                    case `tracked`: clarityDelta += 10; validityDelta += 4; riskDelta -= 6; break;
                    case `peeronly`: clarityDelta += 1; riskDelta += 4; coachKey = `coach_r3_peeronly`; break;
                    case `none`: clarityDelta -= 5; riskDelta += 7; coachKey = `coach_r3_notracked`; break;
                }

                // Early-alert ownership & escalation path.
                switch (d.escalation) {
                    case `named`: clarityDelta += 6; completionDelta += 4; riskDelta -= 5; if (d.checkpoint === `early`) coachKey = `coach_r3_owned`; break;
                    case `advisor`: completionDelta -= 2; riskDelta += 3; break;
                    case `noone`: clarityDelta -= 4; completionDelta -= 4; riskDelta += 7; coachKey = `coach_r3_noowner`; break;
                }

                summaryKey = (d.checkpoint === `early` && d.contribution === `tracked` && d.escalation === `named`) ? `sum_r3_good` :
                             (d.checkpoint === `summative` ? `sum_r3_summative` : `sum_r3_weak`);
            } else if (round === 4) {
                // Allocate the R1.6M support budget & defend the design (Common Error 5: even spread).
                const tg = d.targeted, wr = d.writing, al = d.alert;

                // Targeted tutoring protects the bottom quartile the new rigour will expose; uniform under-serves.
                completionDelta += tg * 10 + al * 5 + wr * 2;
                riskDelta += -tg * 4 - al * 3 + (wr > tg ? 4 : 0);
                clarityDelta += al * 4;

                if (tg >= 0.7 && tg >= wr && tg >= al) {
                    completionDelta += 4; riskDelta -= 4; coachKey = `coach_r4_targeted`;
                } else if (Math.abs(tg - wr) < 0.2 && Math.abs(wr - al) < 0.2) {
                    // Roughly even spread across the three lines — the classic mis-allocation.
                    completionDelta -= 3; riskDelta += 6; coachKey = `coach_r4_even`;
                }

                // If completion collapsed under exam-heavy rigour, only targeted support + early alert can recover it.
                if (ds.completionCollapsed) {
                    if (tg >= 0.7 && al >= 0.4) { completionDelta += 3; }
                    else { completionDelta -= 8; riskDelta += 6; coachKey = `coach_r4_collapse`; }
                }

                // Defend the redesign to the QA panel.
                switch (d.defence) {
                    case `evidence`: validityDelta += 6; clarityDelta += 4; riskDelta -= 12; coachKey = `coach_r4_evidence`; break;
                    case `rigour`: riskDelta += 5; coachKey = `coach_r4_rigour`; break;
                    case `passrate`: validityDelta -= 4; riskDelta += 10; coachKey = `coach_r4_passrate`; break;
                }

                if (d.conviction >= 60) { riskDelta -= 4; clarityDelta += 3; }
                else if (d.conviction <= 25) { riskDelta += 5; clarityDelta -= 3; }

                summaryKey = (tg >= 0.7 && d.defence === `evidence`) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // Resource accounting: meter the marking/support-hour budget (cap displayed at 600).
            if (round === 2) {
                ds.hoursUsed = hours;
            }

            // Completion-collapse dynamic (Common Error 1): high validity from an exam-heavy
            // single instrument, before any checkpoints or targeted support, drags completion
            // toward the 74% pilot floor.
            if (round === 2 && ds.completionCollapsed) {
                completionDelta -= 14;
            }

            // Apply deltas. Completion is a percentage clamped to [50,100]; KPIs 0-100; risk 0-100 (lower better).
            ds.validity = Math.max(0, Math.min(100, Math.round(ds.validity + validityDelta)));
            ds.clarity = Math.max(0, Math.min(100, Math.round(ds.clarity + clarityDelta)));
            ds.completion = Math.max(50, Math.min(100, Math.round(ds.completion + completionDelta)));
            ds.risk = Math.max(0, Math.min(100, Math.round(ds.risk + riskDelta)));

            // An unsustainable (over-budget) design cannot be approved, no matter how
            // valid it looks on paper — QA risk has a hard floor (Common Error 3).
            if (ds.overBudget) ds.risk = Math.max(ds.risk, 45);
            // Skipping cross-section re-moderation leaves a reliability gap the panel flags
            // next — a valid-on-paper scheme that is inconsistent across markers/sections.
            if (ds.cutModeration) ds.risk = Math.max(ds.risk, 40);

            ds.validityHistory.push(ds.validity);
            ds.clarityHistory.push(ds.clarity);
            ds.completionHistory.push(ds.completion);
            ds.riskHistory.push(ds.risk);

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            // Expose composite (0-100) to the reporting/grading layer every period
            // (express/results_utils.php::express_resolveDomainScore reads domainState.performance.overallScore).
            ds.performance = { overallScore: this._composite(ds) };

            return {
                period: state.currentPeriod,
                validity: ds.validity,
                validityDelta: Math.round(validityDelta),
                clarity: ds.clarity,
                clarityDelta: Math.round(clarityDelta),
                completion: ds.completion,
                completionDelta: Math.round(completionDelta),
                risk: ds.risk,
                riskDelta: Math.round(riskDelta),
                hoursUsed: ds.hoursUsed,
                overBudget: ds.overBudget,
                killedGroup: ds.killedGroup,
                completionCollapsed: ds.completionCollapsed,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

        setupUI(uiManager) {
            uiManager.bind(`currentDay`, `currentPeriod`);
            uiManager.bind(`maxPeriods`, `maxPeriods`);

            const self = this;

            uiManager.bind(`validityDisplay`, `domainState.validity`, (v) => Math.round(Number(v)));
            uiManager.bind(`clarityDisplay`, `domainState.clarity`, (v) => Math.round(Number(v)));
            uiManager.bind(`completionDisplay`, `domainState.completion`, (v) => {
                const card = document.querySelector(`.accbydesign-card-completion`);
                if (card) {
                    card.classList.toggle(`accbydesign-completion-low`, Number(v) < 80);
                    card.classList.toggle(`accbydesign-completion-high`, Number(v) >= 90);
                }
                return Math.round(Number(v)) + `%`;
            });
            uiManager.bind(`riskDisplay`, `domainState.risk`, (v) => {
                const card = document.querySelector(`.accbydesign-card-risk`);
                if (card) {
                    card.classList.toggle(`accbydesign-risk-high`, Number(v) >= 60);
                    card.classList.toggle(`accbydesign-risk-low`, Number(v) <= 25);
                }
                return Math.round(Number(v));
            });
            uiManager.bind(`budgetDisplay`, `domainState.hoursUsed`, (v) => {
                const used = Math.round(Number(v));
                const over = used > self.HOUR_BUDGET;
                const bar = document.querySelector(`.accbydesign-budget-bar #budgetDisplay`);
                if (bar) bar.style.color = over ? `#c0392b` : ``;
                const unit = window.mySimulation ? window.mySimulation.t(`hrs_unit`) : `hrs`;
                return `${used} / ${self.HOUR_BUDGET} ${unit}`;
            });

            // Round-1 explicit-gap slider readout.
            const ev = document.getElementById(`evidenceInput`);
            const evReadout = document.getElementById(`evidenceReadout`);
            if (ev && evReadout) {
                evReadout.textContent = ev.value;
                ev.addEventListener(`input`, function() { evReadout.textContent = ev.value; });
            }

            // Round-2 blueprint live total (must hit 100%).
            const weightIds = [`examInput`, `appliedInput`, `peerInput`, `groupInput`];
            const weightReadout = document.getElementById(`weightReadout`);
            const recomputeWeights = function() {
                let total = 0;
                weightIds.forEach((id) => {
                    const el = document.getElementById(id);
                    if (el) total += (parseFloat(el.value) || 0);
                });
                total = Math.round(total);
                if (weightReadout) weightReadout.textContent = total;
                const bar = document.querySelector(`.accbydesign-alloc-readout`);
                if (bar) bar.style.color = (total !== 100) ? `#c0392b` : ``;
            };
            weightIds.forEach((id) => {
                const el = document.getElementById(id);
                if (el) el.addEventListener(`input`, recomputeWeights);
            });
            recomputeWeights();

            // Round-4 support-budget live total (must hit R1.6M).
            const supIds = [`targetedInput`, `writingInput`, `alertInput`];
            const supReadout = document.getElementById(`supportReadout`);
            const recomputeSupport = function() {
                let total = 0;
                supIds.forEach((id) => {
                    const el = document.getElementById(id);
                    if (el) total += (parseFloat(el.value) || 0);
                });
                total = Math.round(total * 10) / 10;
                if (supReadout) supReadout.textContent = total.toFixed(1);
            };
            supIds.forEach((id) => {
                const el = document.getElementById(id);
                if (el) el.addEventListener(`input`, recomputeSupport);
            });
            recomputeSupport();
        }

