        getChartData(state) {
            const ds = state.domainState;
            const labels = ds.validityHistory.map((_, i) => (i === 0 ? window.mySimulation.t(`chart_start`) : `R` + i));
            return {
                accChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.validityHistory },
                        { data: ds.clarityHistory },
                        { data: ds.completionHistory },
                        { data: ds.riskHistory }
                    ]
                }
            };
        }

        _composite(ds) {
            const validity = Math.round(ds.validity);
            const clarity = Math.round(ds.clarity);
            const completion = Math.round(ds.completion);
            const risk = Math.round(ds.risk);
            const completionScore = Math.max(0, Math.min(100, (completion - 50) * 2));
            return Math.max(0, Math.min(100, Math.round(validity * 0.30 + clarity * 0.26 + completionScore * 0.22 + (100 - risk) * 0.22)));
        }

        _cl(key, fallback) {
            try {
                const v = (window.mySimulation && typeof window.mySimulation.t === `function`)
                    ? window.mySimulation.t(key) : key;
                return (v && v !== key) ? v : fallback;
            } catch (e) { return fallback; }
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const validity = Math.round(ds.validity);
            const clarity = Math.round(ds.clarity);
            const completion = Math.round(ds.completion);
            const risk = Math.round(ds.risk);

            // Composite: validity, clarity, completion protection, low QA risk.
            const composite = this._composite(ds);

            const valid = validity >= 60;
            const visible = clarity >= 60;
            const sustained = completion >= 85;
            // QA cannot approve an unsustainable design, one that abolished collaboration,
            // nor one that skipped re-moderation (a reliability gap across sections).
            const approved = risk <= 35 && !ds.overBudget && !ds.killedGroup && !ds.cutModeration;

            let performance = window.mySimulation.t(`grade_redesign`);
            if (valid && visible && sustained && approved && composite >= 75) performance = window.mySimulation.t(`grade_approved`);
            else if (valid && sustained && approved) performance = window.mySimulation.t(`grade_nqf`);
            else if (ds.overBudget) performance = window.mySimulation.t(`grade_unsustainable`);
            else if (ds.killedGroup) performance = window.mySimulation.t(`grade_collab`);
            else if (ds.cutModeration) performance = window.mySimulation.t(`grade_reliability`);
            else if (completion <= 78) performance = window.mySimulation.t(`grade_collapsed`);
            else if (validity < 45) performance = window.mySimulation.t(`grade_validitygap`);
            else if (composite >= 55) performance = window.mySimulation.t(`grade_conditional`);

            const insights = [];
            if (valid && visible && sustained && approved) insights.push(window.mySimulation.t(`insight_approved`));
            else if (ds.killedGroup) insights.push(window.mySimulation.t(`insight_killedgroup`));
            else if (completion <= 78) insights.push(window.mySimulation.t(`insight_collapse`));
            else if (validity < 45) insights.push(window.mySimulation.t(`insight_gap`));
            else insights.push(window.mySimulation.t(`insight_short`));

            if (completion < 85) insights.push(window.mySimulation.t(`insight_completion`));
            else if (completion >= 90 && valid) insights.push(window.mySimulation.t(`insight_balanced`));
            if (ds.overBudget) insights.push(window.mySimulation.t(`insight_overbudget`));
            if (clarity < 45) insights.push(window.mySimulation.t(`insight_invisible`));
            if (valid && visible && risk <= 30 && approved) insights.push(window.mySimulation.t(`insight_defended`));

            return {
                validity: validity,
                clarity: clarity,
                completion: completion,
                risk: risk,
                valid: valid,
                visible: visible,
                sustained: sustained,
                approved: approved,
                met: (valid && visible && sustained && approved && composite >= 75),
                overBudget: !!ds.overBudget,
                killedGroup: !!ds.killedGroup,
                cutModeration: !!ds.cutModeration,
                composite: composite,
                totalScore: composite,
                overallScore: composite,
                performance: performance,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            const T = (window.mySimulation && typeof window.mySimulation.t === `function`)
                ? function(k) { return window.mySimulation.t(k); }
                : function(k) { return k; };
            const s = summary || {};
            const score = (typeof s.overallScore === `number`) ? s.overallScore
                : (typeof s.totalScore === `number` ? s.totalScore
                : (typeof s.composite === `number` ? s.composite : 0));
            const grade = s.performance || ``;
            const met = !!s.met;
            const badge = met
                ? `<span class="accbydesign-cm-badge accbydesign-cm-yes">` + T(`cm_met`) + `</span>`
                : `<span class="accbydesign-cm-badge accbydesign-cm-no">` + T(`cm_notmet`) + `</span>`;
            let failBadge = ``;
            if (s.overBudget) failBadge += ` <span class="accbydesign-cm-badge accbydesign-cm-no">` + T(`cm_unsustainable`) + `</span>`;
            if (s.killedGroup) failBadge += ` <span class="accbydesign-cm-badge accbydesign-cm-no">` + T(`cm_collab`) + `</span>`;
            if (s.cutModeration) failBadge += ` <span class="accbydesign-cm-badge accbydesign-cm-no">` + T(`cm_reliability`) + `</span>`;
            const insights = Array.isArray(s.insights) ? s.insights : [];
            const items = insights.map(function(t) { return `<li>` + t + `</li>`; }).join(``);
            const metrics = ``
                + `<div class="accbydesign-cm-metric"><span class="accbydesign-cm-mv">` + Math.round(s.validity || 0) + `</span><span class="accbydesign-cm-ml">` + T(`cm_m_validity`) + `</span></div>`
                + `<div class="accbydesign-cm-metric"><span class="accbydesign-cm-mv">` + Math.round(s.clarity || 0) + `</span><span class="accbydesign-cm-ml">` + T(`cm_m_clarity`) + `</span></div>`
                + `<div class="accbydesign-cm-metric"><span class="accbydesign-cm-mv">` + (Math.round(s.completion || 0) + `%`) + `</span><span class="accbydesign-cm-ml">` + T(`cm_m_completion`) + `</span></div>`
                + `<div class="accbydesign-cm-metric"><span class="accbydesign-cm-mv">` + Math.round(s.risk || 0) + `</span><span class="accbydesign-cm-ml">` + T(`cm_m_risk`) + `</span></div>`;
            return ``
                + `<div class="accbydesign-completion">`
                +   `<div class="accbydesign-cm-head">`
                +     `<div class="accbydesign-cm-score">` + score + `<span class="accbydesign-cm-score-max">/100</span></div>`
                +     `<div class="accbydesign-cm-grade">` + grade + ` ` + badge + failBadge + `</div>`
                +   `</div>`
                +   `<div class="accbydesign-cm-metrics">` + metrics + `</div>`
                +   `<div class="accbydesign-cm-insights-title">` + T(`cm_debrief`) + `</div>`
                +   `<ul class="accbydesign-cm-insights">` + items + `</ul>`
                + `</div>`;
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.completion <= 80) return window.mySimulation.t(`hint_completion`);
            if (ds.overBudget) return window.mySimulation.t(`hint_overbudget`);
            if (state.currentPeriod >= 2 && ds.validity < 45) return window.mySimulation.t(`hint_validity`);
            if (state.currentPeriod >= 3 && ds.clarity < 45) return window.mySimulation.t(`hint_clarity`);
            if (ds.risk >= 60) return window.mySimulation.t(`hint_risk`);
            if (ds.validity >= 60 && ds.clarity >= 60 && ds.completion >= 85 && ds.risk <= 30) return window.mySimulation.t(`hint_strong`);
            return null;
        }

